// The AI model may end with prose, malformed JSON or a premature final response.
// Only an actual approved output from Sub_Validate_Final_Build can become a recipe.
const item=$input.first().json||{};
function parse(v){
  if(typeof v!=='string')return v;
  const s=v.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');
  try{return JSON.parse(s)}catch(e){return v}
}
function approved(v,depth=0){
 if(depth>8||v==null)return null;
 v=parse(v);
 if(Array.isArray(v)){for(let i=v.length-1;i>=0;i--){const res=approved(v[i],depth+1);if(res)return res;}return null;}
 if(v&&typeof v==='object'){
  if(v.status==='approved'&&v.final_json&&typeof v.final_json==='object')return v.final_json;
  for(const k of ['json','output','response','result','data','items','text','content','observation']){
   if(v[k]!=null){const res=approved(v[k],depth+1);if(res)return res;}
  }
 }
 return null;
}
const steps=Array.isArray(item.intermediateSteps)?item.intermediateSteps:[];
const called=[];let chosen=null;
for(const step of steps){
  const name=String(step?.action?.tool||step?.action?.toolName||'');
  if(name)called.push(name);
  if(name==='Sub_Validate_Final_Build'){
   const parsed=approved(step.observation);
   if(parsed) chosen=parsed;
  }
}
if(chosen){
 if(typeof chosen.name==='string'&&Array.isArray(chosen.ingredients)&&Array.isArray(chosen.steps)
    &&chosen.agentic_review?.status==='approved'){
  return [{json:chosen}];
 }
 return [{json:{error:'Validator output was approved but its recipe payload was invalid',code:'INVALID_VALIDATOR_OUTPUT'}}];
}
// Ordinary bypass branches, e.g. not_food or no_query, produce their own explicit error.
if(typeof item.error==='string')return [{json:item}];
if(String(item.output||'').trim()==='NO_MATCH')return [{json:{error:'No recipe matched your request and current filters.',code:'NO_MATCH',tools_called:called}}];
// Fail closed: no unverified model output ever reaches the user as a recipe.
return [{json:{error:steps.length?'The agent stopped without a validated recipe. Retry or use a stronger Ollama tool-calling model.':'The agent did not call the required tools. Check the Ollama model tool-calling support.',
 code:'AGENT_DID_NOT_VALIDATE',tools_called:called}}];
